/GuessTheGame-Web/quizoria/media/commons/meme-lolcat-example.jpg","source_url":"https://commons.wikimedia.org/wiki/File:CatLolCatExample.jpg","answer_index":1},{"id":"meme2-beast-cat-easy-1","image_key":"qm13-beastcat","difficulty":"easy","prompt_cs":"Která kočičí meme postavička je na obrázku?","prompt_en":"Which cat meme character is pictured?","options":[{"key":0,"cs":"Bingus","en":"Bingus"},{"key":1,"cs":"Grumpy Cat","en":"Grumpy Cat"},{"key":2,"cs":"Beast Cat","en":"Beast Cat"},{"key":3,"cs":"Doge","en":"Doge"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-beast-cat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Beast_Cat_Original_(Meme).jpg","answer_index":2},{"id":"meme2-beast-cat-medium-1","image_key":"qm13-beastcat","difficulty":"medium","prompt_cs":"Jakou reakci bys s memem Beast Cat nejlépe vyjádřil?","prompt_en":"What reaction suits a Beast Cat meme?","options":[{"key":0,"cs":"Tiché soustředění","en":"Quiet concentration"},{"key":1,"cs":"Přísné pracovní oznámení","en":"A formal workplace announcement"},{"key":2,"cs":"Romantickou žádost","en":"A romantic request"},{"key":3,"cs":"Přehnaně divokou či chaotickou náladu","en":"An exaggerated wild or chaotic mood"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-beast-cat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Beast_Cat_Original_(Meme).jpg","answer_index":3},{"id":"meme2-beast-cat-hard-1","image_key":"qm13-beastcat","difficulty":"hard","prompt_cs":"Co dělá absurdní kočičí memy typu Beast Cat vtipnými?","prompt_en":"What makes absurd cat memes like Beast Cat funny?","options":[{"key":0,"cs":"Nečekaně přehnaný výraz a nesmyslná situace","en":"An unexpectedly over-the-top face and absurd situation"},{"key":1,"cs":"Zcela vážná reklama","en":"A totally serious advertisement"},{"key":2,"cs":"Přesný návod k použití","en":"An exact user manual"},{"key":3,"cs":"Důležitá dopravní zpráva","en":"An important traffic report"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-beast-cat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Beast_Cat_Original_(Meme).jpg","answer_index":0},{"id":"meme2-meerkat-easy-1","image_key":"qm13-meerkat2024","difficulty":"easy","prompt_cs":"Jaké zvíře je hvězdou tohoto memu?","prompt_en":"Which animal stars in this meme?","options":[{"key":0,"cs":"Liška","en":"Fox"},{"key":1,"cs":"Surikata","en":"Meerkat"},{"key":2,"cs":"Panda","en":"Panda"},{"key":3,"cs":"Vydra","en":"Otter"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-meerkat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Meerkat_meme.jpg","answer_index":1},{"id":"meme2-meerkat-medium-1","image_key":"qm13-meerkat2024","difficulty":"medium","prompt_cs":"Který typ reakce by se k memu se surikatou hodil?","prompt_en":"Which reaction fits this meerkat meme?","options":[{"key":0,"cs":"Taneční krok","en":"A dance move"},{"key":1,"cs":"Vzdušný souboj","en":"An aerial battle"},{"key":2,"cs":"Přehnaně zvídavý pohled","en":"An exaggerated curious stare"},{"key":3,"cs":"Úplně nezaujatý spánek","en":"A totally uninterested nap"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-meerkat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Meerkat_meme.jpg","answer_index":2},{"id":"meme2-meerkat-hard-1","image_key":"qm13-meerkat2024","difficulty":"hard","prompt_cs":"Proč fungují memy se zvířaty, která mají lidsky působící výrazy?","prompt_en":"Why do memes with human-like animal expressions work?","options":[{"key":0,"cs":"Zvířata mluví anglicky","en":"Animals actually speak English"},{"key":1,"cs":"Každé zvíře je slavný herec","en":"Every animal is a famous actor"},{"key":2,"cs":"Každý takový obrázek je reklama","en":"Every such image is an advertisement"},{"key":3,"cs":"Promítáme do jejich výrazu lidské situace a emoce","en":"We project human situations and emotions onto them"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-meerkat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Meerkat_meme.jpg","answer_index":3}]'::jsonb) AS x(
  id text,image_key text,difficulty text,prompt_cs text,prompt_en text,
  options jsonb,answer_index integer,image_url text,source_url text
 )
)
UPDATE arcade_private.quizoria_meme_questions q
SET prompt_cs=x.prompt_cs,
    prompt_en=x.prompt_en,
    options=x.options,
    answer_index=x.answer_index,
    image_url=x.image_url
FROM content x
JOIN arcade_private.foxey_media_assets a ON a.asset_key=x.image_key
WHERE q.image_key=x.image_key AND q.difficulty=x.difficulty
  AND a.status='approved' AND a.commercial_use AND a.redistribution_allowed
  AND a.source_url=x.source_url
  AND x.image_url LIKE 'https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-%';
COMMIT;
